[Expected Approach - 1] Using Sorting - O(n log(n)) Time and O(n) SpaceThe idea is to calculate how many soldiers need to be added to each troop to make it lucky, means divisible by k. If a troop is already lucky, the cost is zero. Otherwise, the cost to make it lucky is calculated as k - (arr[i] % k). We collect these costs for all troops and sort them in increasing order. Since we need at least half of the troops to be lucky, we select the smallest ceil(n / 2) costs and add them.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int minSoldiers(vector<int>& arr, int k) {
    int n = arr.size();
    int need = (n + 1) / 2;
    vector<int> costs;

    for (int num : arr) {
        if (num % k == 0) {
            costs.push_back(0);
        } else {
            costs.push_back(k - (num % k));
        }
    }

    // Sort the costs in ascending order
    sort(costs.begin(), costs.end());

    // Add up the smallest `need` costs
    int total = 0;
    for (int i = 0; i < need; ++i) {
        total += costs[i];
    }

    return total;
}

int main() {
    vector<int> arr = {3, 5, 6, 7, 9, 11};
    int k = 4;
    cout << minSoldiers(arr, k) << endl;
    return 0;
}


