[Expected Approach 2] Using Min HeapWe can further optimize by first counting how many troops are already lucky. If that’s enough, we return zero. Otherwise, we compute costs only for the unlucky troops and pick the smallest ones needed to reach the target, avoiding full sorting.
            C++

    #include <iostream>
#include <vector>
#include <queue>

using namespace std;

int minSoldiers(vector<int>& arr, int k) {
    int n = arr.size();
    int need = (n + 1) / 2;
    int lucky = 0;

    // Min-heap for storing costs to make a troop lucky
    priority_queue<int, vector<int>, greater<int>> pq;

    for (int num : arr) {
        if (num % k == 0) {
            ++lucky;
        } else {
            pq.push(k - (num % k));
        }
    }

    // If already enough lucky troops, cost is 0
    if (lucky >= need) return 0;

    int total = 0;
    int req = need - lucky;

    // Take smallest required costs from heap
    for (int i = 0; i < req && !pq.empty(); ++i) {
        total += pq.top();
        pq.pop();
    }

    return total;
}

int main() {
    vector<int> arr = {3, 5, 6, 7, 9, 11};
    int k = 4;
    cout << minSoldiers(arr, k) << endl;
    return 0;
}


